using System;
using System.Collections.Generic;
using System.Drawing;
using System.Windows.Forms;
namespace EanEtikety {
public partial class MainForm {
 CheckBox gs1Mode=new CheckBox{Text=Loc.T("Použiť GS1 AI"),AutoSize=true};Button gs1Button;List<AiValue> aiValues=new List<AiValue>();
 void Gs1State(){bool code128=kind.SelectedIndex>=0&&MoreBarcodes.Kinds[kind.SelectedIndex]==128;gs1Mode.Enabled=code128;gs1Button.Enabled=code128;ean.Enabled=!(code128&&gs1Mode.Checked);if(code128&&gs1Mode.Checked){try{formatHint.Text=Gs1.Human(aiValues);}catch{formatHint.Text=Loc.T("Nastavte identifikátory a ich dáta tlačidlom Identifikátory…");}}else if(kind.SelectedIndex>=0)formatHint.Text=MoreBarcodes.Hint(MoreBarcodes.Kinds[kind.SelectedIndex]);}
 static List<AiValue> CopyAi(List<AiValue> items){var result=new List<AiValue>();if(items!=null)foreach(var v in items)result.Add(new AiValue{AI=v.AI,Data=v.Data});return result;}
 void EditGs1(){using(var dialog=new Form{Text=Loc.T("GS1-128 – aplikačné identifikátory"),Size=new Size(960,650),MinimumSize=new Size(800,540),StartPosition=FormStartPosition.CenterParent,Font=Font,ShowInTaskbar=false}){
  var root=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(16),ColumnCount=1,RowCount=4};root.RowStyles.Add(new RowStyle(SizeType.Absolute,60));root.RowStyles.Add(new RowStyle(SizeType.Percent,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,100));root.RowStyles.Add(new RowStyle(SizeType.Absolute,48));dialog.Controls.Add(root);
  var top=new FlowLayoutPanel{Dock=DockStyle.Fill};var select=new ModernComboBox{Width=480,DropDownStyle=ComboBoxStyle.DropDownList,Margin=new Padding(0,6,12,0)};ComboStyle(select);foreach(var d in Gs1.Catalog)select.Items.Add(d);select.SelectedIndex=2;top.Controls.Add(select);root.Controls.Add(top,0,0);
  var rows=new DataGridView{Dock=DockStyle.Fill,AllowUserToAddRows=false,AllowUserToDeleteRows=false,AutoSizeColumnsMode=DataGridViewAutoSizeColumnsMode.Fill,SelectionMode=DataGridViewSelectionMode.FullRowSelect,MultiSelect=false,RowHeadersVisible=false,RowTemplate={Height=34}};rows.Columns.Add(new DataGridViewTextBoxColumn{HeaderText="AI",ReadOnly=true,FillWeight=50,SortMode=DataGridViewColumnSortMode.NotSortable});rows.Columns.Add(new DataGridViewTextBoxColumn{HeaderText=Loc.T("Význam / formát"),ReadOnly=true,FillWeight=280,SortMode=DataGridViewColumnSortMode.NotSortable});rows.Columns.Add(new DataGridViewTextBoxColumn{HeaderText=Loc.T("Dáta"),FillWeight=220,SortMode=DataGridViewColumnSortMode.NotSortable});root.Controls.Add(rows,0,1);
  Action<string,string> add=delegate(string code,string data){var d=Gs1.Find(code);rows.Rows.Add(code,Loc.AiName(d.Name)+" · "+(d.Variable?"1–":"")+d.Length+(d.Numeric?Loc.T(" číslic"):Loc.T(" znakov")),data);};foreach(var v in aiValues)add(v.AI,v.Data);
  Func<List<AiValue>> read=delegate{rows.EndEdit();var items=new List<AiValue>();foreach(DataGridViewRow r in rows.Rows)items.Add(new AiValue{AI=Convert.ToString(r.Cells[0].Value),Data=Convert.ToString(r.Cells[2].Value)});return items;};
  top.Controls.Add(Btn(Loc.T("Pridať"),delegate{if(rows.Rows.Count>=20)return;add(((AiDefinition)select.SelectedItem).Code,"");rows.CurrentCell=rows.Rows[rows.Rows.Count-1].Cells[2];rows.BeginEdit(true);}));
  var report=new Label{Dock=DockStyle.Fill,Padding=new Padding(0,12,0,0)};root.Controls.Add(report,0,2);Action validate=delegate{try{var items=read();report.Text=Gs1.Human(items)+Loc.T("\r\nPoradie riadkov určuje poradie v kóde. FNC1 sa vkladá automaticky. ")+string.Join(" ",Gs1.Warnings(items).ToArray());}catch(Exception ex){report.Text=ex.Message;}};
  var bottom=new FlowLayoutPanel{Dock=DockStyle.Fill};Action<int> move=delegate(int delta){rows.EndEdit();if(rows.CurrentCell==null)return;int i=rows.CurrentCell.RowIndex,j=i+delta;if(j<0||j>=rows.Rows.Count)return;object[] cells={rows.Rows[i].Cells[0].Value,rows.Rows[i].Cells[1].Value,rows.Rows[i].Cells[2].Value};rows.Rows.RemoveAt(i);rows.Rows.Insert(j,cells);rows.CurrentCell=rows.Rows[j].Cells[2];validate();};bottom.Controls.Add(Btn(Loc.T("↑ Vyššie"),delegate{move(-1);}));bottom.Controls.Add(Btn(Loc.T("↓ Nižšie"),delegate{move(1);}));bottom.Controls.Add(Btn(Loc.T("Odstrániť"),delegate{if(rows.CurrentCell!=null)rows.Rows.RemoveAt(rows.CurrentCell.RowIndex);validate();}));bottom.Controls.Add(Btn(Loc.T("Skontrolovať"),delegate{validate();}));bottom.Controls.Add(Btn(Loc.T("Použiť"),delegate{try{var items=read();Gs1.Payload(items);aiValues=CopyAi(items);dialog.DialogResult=DialogResult.OK;}catch(Exception ex){report.Text=ex.Message;}}));var cancel=Btn(Loc.T("Zrušiť"),delegate{dialog.DialogResult=DialogResult.Cancel;});bottom.Controls.Add(cancel);dialog.CancelButton=cancel;root.Controls.Add(bottom,0,3);ApplyColors(dialog);validate();if(dialog.ShowDialog(this)==DialogResult.OK){gs1Mode.Checked=true;Gs1State();Changed(this,EventArgs.Empty);timer.Stop();UpdatePreview();}
 }}
}
}
